var CORPUS='the cat sat on the mat the cat ate the fish a dog ran to the mat the fish swam in the sea';
function tokenize(s){ return String(s).toLowerCase().match(/[a-z0-9]+/g)||[]; }
function train(corpus){ corpus=corpus||CORPUS; var toks=tokenize(corpus); var vocab={}; var n=toks.length;
  for(var i=0;i<n;i++){ vocab[toks[i]]=(vocab[toks[i]]||0)+1; }
  return {vocab:vocab, total:n, V:Object.keys(vocab).length}; }
function perplexity(model, sentence){ var toks=tokenize(sentence); if(!toks.length) return 1;
  var V=model.V||1, logSum=0;
  for(var i=0;i<toks.length;i++){ var c=model.vocab[toks[i]]||0; var p=(c+1)/(model.total+V); logSum+=Math.log(p); }
  return Math.exp(-logSum/toks.length); }
var EXPORTS={CORPUS:CORPUS,tokenize:tokenize,train:train,perplexity:perplexity};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PerplexityForgePure = EXPORTS; }
